"""A standalone store API, implemented with FastAPI.

This is the second independent implementation of the behavioral contract in
``tests/fixtures/external_apps/contract/CONTRACT.md``. It is a plausible small
API service: its own authentication, its own database, its own authorization,
its own OpenAPI document (generated by FastAPI).

It knows nothing about Mizan. It does not import it, and it never calls it.

    python app.py --db store.sqlite --port 8000 --vulnerability clean
"""

from __future__ import annotations

import argparse
import os
import secrets
import sqlite3
import time
from dataclasses import dataclass
from typing import Any

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

#: The variants a deployment can run with.
VARIANTS = ("clean", "read", "write", "both")

#: Test credentials, injected per run through the environment.
DEFAULT_CREDENTIALS = {
    "alice": "MIZAN_TEST_ALICE",
    "bob": "MIZAN_TEST_BOB",
    "root": "MIZAN_TEST_ROOT",
}

#: The seeded orders, owned by root, so a cross-user read and a cross-user
#: write are both possible without the test creating anything.
SEED_ORDERS = [
    ("ord-seed-1", "root", "SKU-SEED-1", 2, "created"),
    ("ord-seed-2", "root", "SKU-SEED-2", 1, "created"),
]


@dataclass
class Settings:
    """The deployment's configuration."""

    vulnerability: str
    credentials: dict[str, str]


# --------------------------------------------------------------------------- #
# Storage
# --------------------------------------------------------------------------- #


def connect(path: str) -> sqlite3.Connection:
    connection = sqlite3.connect(path, timeout=15)
    connection.row_factory = sqlite3.Row
    return connection


SCHEMA = """
CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    password TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'user'
);
CREATE TABLE IF NOT EXISTS tokens (
    token TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    created_at REAL NOT NULL
);
CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY,
    owner_id TEXT NOT NULL,
    sku TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    status TEXT NOT NULL,
    created_at REAL NOT NULL
);
"""


def initialise(path: str, settings: Settings) -> None:
    """Create the schema and seed the users and the orders."""
    connection = connect(path)
    with connection:
        connection.executescript(SCHEMA)
        for user, password in settings.credentials.items():
            role = "admin" if user == "root" else "user"
            connection.execute(
                "INSERT OR IGNORE INTO users (id, password, role) VALUES (?, ?, ?)",
                (user, password, role),
            )
        for order_id, owner, sku, quantity, status in SEED_ORDERS:
            connection.execute(
                "INSERT OR IGNORE INTO orders (id, owner_id, sku, quantity, status, created_at)"
                " VALUES (?, ?, ?, ?, ?, ?)",
                (order_id, owner, sku, quantity, status, time.time()),
            )
    connection.close()


# --------------------------------------------------------------------------- #
# API models
# --------------------------------------------------------------------------- #


class LoginRequest(BaseModel):
    username: str = Field(min_length=1, examples=["alice"])
    password: str = Field(min_length=1, examples=["alice-secret"])


class LoginResponse(BaseModel):
    token: str
    user_id: str


class Me(BaseModel):
    id: str
    role: str
    owner_id: str


class Order(BaseModel):
    id: str
    owner_id: str
    sku: str
    quantity: int
    status: str
    created_at: float


class OrderCreate(BaseModel):
    """A multi-field body, so the learning phase meets a real requirement."""

    sku: str = Field(min_length=1, examples=["SKU-1"])
    quantity: int = Field(ge=1, examples=[1])
    note: str | None = Field(default=None, max_length=200)


class OrderUpdate(BaseModel):
    status: str = Field(min_length=1, examples=["cancelled"])
    reason: str | None = Field(default=None, max_length=200)


class Health(BaseModel):
    status: str


# --------------------------------------------------------------------------- #
# The application
# --------------------------------------------------------------------------- #


def create_app(database: str, settings: Settings) -> FastAPI:
    """Build the application."""
    app = FastAPI(
        title="Store API",
        version="1.0.0",
        description="A standalone store API. It knows nothing about Mizan.",
    )
    app.state.database = database
    app.state.settings = settings

    def current_user(request: Request) -> tuple[str, str]:
        """The identity behind the bearer token."""
        header = request.headers.get("authorization", "")
        if not header.startswith("Bearer "):
            raise HTTPException(status_code=401, detail="missing bearer token")
        token = header[len("Bearer ") :].strip()
        connection = connect(request.app.state.database)
        try:
            row = connection.execute("SELECT user_id FROM tokens WHERE token = ?", (token,)).fetchone()
        finally:
            connection.close()
        if row is None:
            raise HTTPException(status_code=401, detail="unknown token")
        connection = connect(request.app.state.database)
        try:
            user = connection.execute("SELECT id, role FROM users WHERE id = ?", (row["user_id"],)).fetchone()
        finally:
            connection.close()
        if user is None:
            raise HTTPException(status_code=401, detail="unknown user")
        return user["id"], user["role"]

    def is_admin(user_id: str) -> bool:
        connection = connect(app.state.database)
        try:
            row = connection.execute("SELECT role FROM users WHERE id = ?", (user_id,)).fetchone()
        finally:
            connection.close()
        return bool(row) and row["role"] == "admin"

    def may_read(order: sqlite3.Row, user_id: str) -> bool:
        """Whether the caller may read this order."""
        if settings.vulnerability in {"read", "both"}:
            return True
        return order["owner_id"] == user_id or is_admin(user_id)

    def may_write(order: sqlite3.Row, user_id: str) -> bool:
        """Whether the caller may change this order."""
        if settings.vulnerability in {"write", "both"}:
            return True
        return order["owner_id"] == user_id or is_admin(user_id)

    @app.exception_handler(HTTPException)
    def http_error(request: Request, exc: HTTPException) -> JSONResponse:
        # The existence of a resource is not the caller's business.
        if exc.status_code == 403:
            exc.status_code = 404
            exc.detail = "order not found"
        return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})

    @app.get("/health", response_model=Health)
    def health() -> Health:
        return Health(status="ok")

    @app.post("/login", response_model=LoginResponse)
    def login(payload: LoginRequest) -> LoginResponse:
        connection = connect(app.state.database)
        try:
            row = connection.execute(
                "SELECT id FROM users WHERE id = ? AND password = ?",
                (payload.username, payload.password),
            ).fetchone()
        finally:
            connection.close()
        if row is None:
            raise HTTPException(status_code=401, detail="invalid credentials")
        token = secrets.token_urlsafe(32)
        connection = connect(app.state.database)
        with connection:
            connection.execute(
                "INSERT INTO tokens (token, user_id, created_at) VALUES (?, ?, ?)",
                (token, payload.username, time.time()),
            )
        connection.close()
        return LoginResponse(token=token, user_id=payload.username)

    @app.get("/me", response_model=Me)
    def me(user: tuple[str, str] = Depends(current_user)) -> Me:
        return Me(id=user[0], role=user[1], owner_id=user[0])

    @app.get("/orders", response_model=dict[str, list[Order]])
    def list_orders(user: tuple[str, str] = Depends(current_user)) -> dict[str, Any]:
        connection = connect(app.state.database)
        try:
            rows = connection.execute(
                "SELECT * FROM orders WHERE owner_id = ? ORDER BY created_at", (user[0],)
            ).fetchall()
        finally:
            connection.close()
        return {"orders": [Order(**dict(row)) for row in rows]}

    @app.post("/orders", response_model=Order, status_code=201)
    def create_order(payload: OrderCreate, user: tuple[str, str] = Depends(current_user)) -> Order:
        order_id = f"ord-{secrets.token_hex(6)}"
        connection = connect(app.state.database)
        with connection:
            connection.execute(
                "INSERT INTO orders (id, owner_id, sku, quantity, status, created_at)"
                " VALUES (?, ?, ?, ?, 'created', ?)",
                (order_id, user[0], payload.sku, payload.quantity, time.time()),
            )
        connection.close()
        return Order(
            id=order_id,
            owner_id=user[0],
            sku=payload.sku,
            quantity=payload.quantity,
            status="created",
            created_at=time.time(),
        )

    @app.get("/orders/{order_id}", response_model=Order)
    def read_order(order_id: str, user: tuple[str, str] = Depends(current_user)) -> Order:
        connection = connect(app.state.database)
        try:
            row = connection.execute("SELECT * FROM orders WHERE id = ?", (order_id,)).fetchone()
        finally:
            connection.close()
        if row is None:
            raise HTTPException(status_code=404, detail="order not found")
        if not may_read(row, user[0]):
            raise HTTPException(status_code=403, detail="order not found")
        return Order(**dict(row))

    @app.put("/orders/{order_id}", response_model=Order)
    def update_order(
        order_id: str,
        payload: OrderUpdate,
        user: tuple[str, str] = Depends(current_user),
    ) -> Order:
        connection = connect(app.state.database)
        try:
            row = connection.execute("SELECT * FROM orders WHERE id = ?", (order_id,)).fetchone()
        finally:
            connection.close()
        if row is None:
            raise HTTPException(status_code=404, detail="order not found")
        if not may_write(row, user[0]):
            raise HTTPException(status_code=403, detail="order not found")
        connection = connect(app.state.database)
        with connection:
            connection.execute("UPDATE orders SET status = ? WHERE id = ?", (payload.status, order_id))
        connection.close()
        connection = connect(app.state.database)
        try:
            updated = connection.execute("SELECT * FROM orders WHERE id = ?", (order_id,)).fetchone()
        finally:
            connection.close()
        return Order(**dict(updated))

    return app


def main() -> None:  # pragma: no cover - the entry point
    parser = argparse.ArgumentParser(description="Run the standalone store API")
    parser.add_argument("--db", default="store.sqlite")
    parser.add_argument("--port", type=int, default=0)
    parser.add_argument(
        "--vulnerability",
        default="clean",
        choices=list(VARIANTS),
        help="which authorization weakness to inject",
    )
    arguments = parser.parse_args()

    if arguments.vulnerability not in VARIANTS:
        raise SystemExit(f"unknown variant: {arguments.vulnerability}")

    credentials = {user: os.environ.get(env, f"{user}-secret") for user, env in DEFAULT_CREDENTIALS.items()}
    settings = Settings(vulnerability=arguments.vulnerability, credentials=credentials)
    initialise(arguments.db, settings)

    import uvicorn

    uvicorn.run(create_app(arguments.db, settings), host="127.0.0.1", port=arguments.port)


if __name__ == "__main__":  # pragma: no cover
    main()
